// Zweck: Detailseite für ein einzelnes Cover-Gerät als HTML ausliefern.
// Eingabe:  msg.req.params.device_id – Geräte-ID aus der URL
//           msg.req.query.saved     – '1' wenn gerade gespeichert wurde (Notice anzeigen)
// Ausgabe:  msg.payload – vollständiger HTML-String
//           msg.statusCode – 200 oder 500

const coverAutomation = global.get("coverAutomation");

// Sicherheitscheck: Helper muss aus /data/lib/ geladen sein.
if (!coverAutomation || typeof coverAutomation.renderDetailPage !== "function") {
    msg.statusCode = 500;
    msg.headers    = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload    = "cover automation helper fehlt – /data/lib/cover_automation.js prüfen";
    return msg;
}

const runtime  = global.get("smarthome_runtime");
const params   = msg.req && msg.req.params ? msg.req.params : {};
const query    = msg.req && msg.req.query  ? msg.req.query  : {};
const deviceId = params.device_id || "";

// Kurze Erfolgsmeldung nach dem Speichern der Zeitkonfiguration.
const notice = query.saved === "1" ? "Zeitautomatik gespeichert." : "";

const result = coverAutomation.renderDetailPage(runtime, deviceId, notice);
msg.statusCode = result.statusCode || 200;
msg.headers    = { "Content-Type": "text/html; charset=utf-8" };
msg.payload    = result.html;
return msg;

// Zweck: Zeitautomatik-Konfiguration für ein Cover-Gerät persistent speichern.
// Eingabe:  msg.req.params.device_id – Geräte-ID aus der URL
//           msg.payload – JSON-Body mit den Zeitslots (time, position, enabled)
// Ausgabe:  msg.payload – { ok, device_id, config } oder { ok: false, error, message }

const coverAutomation = global.get("coverAutomation");
const timeHelpers     = global.get("timeHelpers");
const runtime         = global.get("smarthome_runtime");

if (!coverAutomation || typeof coverAutomation.saveDeviceConfig !== "function") {
    msg.statusCode = 500;
    msg.payload    = { ok: false, error: "cover_automation_unavailable", message: "cover automation helper fehlt" };
    return msg;
}

const params   = msg.req && msg.req.params ? msg.req.params : {};
const deviceId = params.device_id || "";

// Gerät muss im Runtime bekannt sein, bevor eine Konfiguration gespeichert wird.
const device = runtime && runtime.devices ? runtime.devices[deviceId] : null;
if (!device) {
    msg.statusCode = 404;
    msg.payload    = { ok: false, error: "device_not_found", message: `Gerät '${deviceId}' nicht gefunden` };
    return msg;
}

const result = coverAutomation.saveDeviceConfig(deviceId, msg.payload, timeHelpers.nowIso());
msg.statusCode = result.ok ? 200 : 400;
msg.payload    = result.ok
    ? { ok: true,  device_id: deviceId, config: result.config }
    : { ok: false, error: result.error, message: result.message };
return msg;

// Zweck: Minütlich prüfen, ob ein Zeitslot für ein Cover-Gerät fällig ist,
//        und die entsprechenden MQTT-Befehle direkt ausgeben.
//
// Ausgabe: Array von MQTT-Nachrichten (je Gerät und fälligem Slot eine Message)
//          oder null, wenn keine Befehle fällig sind.
//
// OPTIMIERUNG: Vorher hatte diese Function fälschlicherweise zwei Outputs
// (Output 1 = Messages, Output 2 = null). Der zweite Output war nie verdrahtet.
// Jetzt: Ein Output, direkte Rückgabe des Message-Arrays oder null.

const coverAutomation = global.get("coverAutomation");
const commandMinimal  = global.get("commandMinimal");
const timeHelpers     = global.get("timeHelpers");
const runtime         = global.get("smarthome_runtime");

// Wenn Helper fehlen, still abbrechen – kein Fehler-Spam jede Minute.
if (!coverAutomation || typeof coverAutomation.buildDueMessages !== "function") {
    return null;
}

const now    = timeHelpers.nowIso();
const result = coverAutomation.buildDueMessages(runtime, commandMinimal, now);

// Aufgetretene Fehler (z. B. ungültige Konfiguration) als Warnung loggen.
if (Array.isArray(result.errors) && result.errors.length > 0) {
    node.warn(result.errors.map(
        (entry) => `${entry.device_id} ${entry.slot}: ${entry.error}`
    ).join(" | "));
}

// Keine fälligen Befehle → Nachricht verwerfen, kein unnötiger MQTT-Traffic.
if (!Array.isArray(result.messages) || result.messages.length === 0) {
    return null;
}

// Direkte Rückgabe: Node-RED sendet jede Message im Array einzeln an den MQTT-Out.
return result.messages;
